_map:
var user = item.user && item.user.screen_name;
var ts = item._ts;
var m = item.text && item.text.match(/#([\w\u0080-\uFFFF]+)/gi);
var i, tag;
if (m) {
  for (i = 0; i < m.length; i++) {
    tag = m[i].toLowerCase();
    if (tag.length > 1 && tag.length <= 64) {
      emit(tag, { user: user, _ts: ts });
    }
  }
}

_reduce:
var res = { count: 0, users: {}, minTs: null, maxTs: null };
var mergeOne = function (v) {
  if (!v || !v.user) {
    return;
  }
  res.count += 1;
  res.users[v.user] = 1;
  if (v._ts) {
    if (res.minTs === null || v._ts < res.minTs) {
      res.minTs = v._ts;
    }
    if (res.maxTs === null || v._ts > res.maxTs) {
      res.maxTs = v._ts;
    }
  }
};
var mergeReduced = function (r) {
  var u, us;
  if (!r) {
    return;
  }
  res.count += r.count || 0;
  us = r.users || {};
  for (u in us) {
    if (us.hasOwnProperty(u)) {
      res.users[u] = 1;
    }
  }
  if (r.minTs !== null && r.minTs !== undefined) {
    if (res.minTs === null || r.minTs < res.minTs) {
      res.minTs = r.minTs;
    }
  }
  if (r.maxTs !== null && r.maxTs !== undefined) {
    if (res.maxTs === null || r.maxTs > res.maxTs) {
      res.maxTs = r.maxTs;
    }
  }
};
if (rereduce === false) {
  values.forEach(mergeOne);
} else {
  values.forEach(mergeReduced);
}
emit(res);

_finalize:
var out = [], i, row, key, s, users, spanMin, rate;
for (i = 0; i < reduction.length; i++) {
  row = reduction[i];
  key = row[0];
  s = row[1];
  if (!s || !s.count) {
    continue;
  }
  users = s.users || {};
  spanMin = 5;
  if (s.minTs !== null && s.maxTs !== null && s.maxTs > s.minTs) {
    spanMin = Math.max(1, (s.maxTs - s.minTs) / 60000);
  }
  rate = s.count / spanMin;
  out.push([key, {
    label: key,
    x: Math.round(rate * 100) / 100,
    y: Object.keys(users).length,
    size: s.count
  }]);
}
out.sort(function (a, b) {
  return b[1].size - a[1].size;
});
if (out.length > 25) {
  out.length = 25;
}
emit(out);
